    with NWBHDF5IO(path,'r',load_namespaces=True) as io:
        nwb=io.read()
        trials=nwb.trials.to_dataframe()
        go=np.asarray(nwb.acquisition['BehavioralEvents'].time_series['go_start_times'].timestamps[:])
        sample=np.asarray(nwb.acquisition['BehavioralEvents'].time_series['sample_start_times'].timestamps[:])
        starts=trials['start_time'].to_numpy(); stops=trials['stop_time'].to_numpy()
        diffs=[]
        missing=0
        for st,sp,g in zip(starts,stops,go):
            s=sample[(sample>=st)&(sample<=sp)]
            if len(s)==0:
                missing+=1
            else:
                diffs.append(round(float(g-s[-1]),4))
        vals={v:diffs.count(v) for v in sorted(set(diffs))[:10]}
        print(path.split('/')[-1], 'missing', missing, 'unique last go-sample', vals)
